function renderSearchResults(query) {
  var normalized = query.trim();
  if (!normalized) return;
  var results = getSearchResults(normalized);
  var items = results.map(function(video) {
    return '<article class="video-item"><div class="video-content"><a href="#" class="video-title">' + video.title + '</a><p class="video-description">' + (video.desc || video.description || '') + '</p></div></article>';
  }).join('');
  history.pushState({query: normalized}, '', '/search/' + encodeURIComponent(normalized));
  document.getElementById('mainContent').innerHTML = '<div class="page-container"><header class="page-header"><h1 class="page-title">Search Results: ' + normalized + '</h1><p class="page-subtitle">' + results.length + ' matching videos</p></header><div class="video-list-container"><div class="video-list">' + items + '</div></div></div>';
}

function submitTopSearch() {
  renderSearchResults(document.getElementById('searchInput').value);
}

function init() {
  renderHome();
  document.getElementById('searchBtn').addEventListener('click', submitTopSearch);
  document.getElementById('searchInput').addEventListener('keydown', function(event) {
    if (event.key === 'Enter') {
      event.preventDefault();
      submitTopSearch();
    }
  });
}
